// Build one digest (HTML for email, mrkdwn for Slack) from the new TED notices.
// The actor runs in alertMode, so it only returns notices it has not returned before
// for this alertStateKey. If there is nothing new, stop here (no email / Slack).
const notices = $input.all().map(i => i.json).filter(n => n.publicationNumber);
if (notices.length === 0) return [];

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const value = n => n.estimatedValue && n.estimatedValue.amount
  ? `${Number(n.estimatedValue.amount).toLocaleString('en')} ${n.estimatedValue.currency || ''}`.trim() : 'n/a';
const attribution = notices[0].attribution;

const rows = notices.map(n => `<tr>
  <td><a href="${esc(n.url)}">${esc(n.publicationNumber)}</a></td>
  <td>${esc(n.title)}</td>
  <td>${esc((n.buyerNames || []).join(', '))} (${esc((n.buyerCountries || []).join(', '))})</td>
  <td>${esc(n.mainCpv)}</td>
  <td>${esc(n.tenderDeadline || 'n/a')}</td>
  <td>${esc(value(n))}</td>
</tr>`).join('\n');

const html = `<p>${notices.length} new EU tender notice(s) matching your CPV / country filter.</p>
<table border="1" cellpadding="4" cellspacing="0">
<tr><th>Notice</th><th>Title</th><th>Buyer</th><th>Main CPV</th><th>Deadline</th><th>Est. value</th></tr>
${rows}
</table>
<p style="font-size:small">${esc(attribution)}</p>`;

const slack = [`*${notices.length} new EU tender notice(s)*`]
  .concat(notices.slice(0, 20).map(n => `• <${n.url}|${n.publicationNumber}> ${n.title} — deadline ${n.tenderDeadline || 'n/a'}`))
  .concat(notices.length > 20 ? [`…and ${notices.length - 20} more`] : [])
  .concat([`_${attribution}_`])
  .join('\n');

return [{ json: { count: notices.length, subject: `${notices.length} new EU tenders (TED) for your CPV codes`, html, slack } }];
